INSERT INTO public.biblioteca_vectores (id,coleccion,materia,contenido,num_articulo,fuente,metadata,embedding,jurisdiccion,fuente_tipo,es_norma_vigente,revision_pendiente,instrumento_id,num_articulo_norm,hash_contenido,ingest_batch,ingested_at) VALUES
('OLA5_CF_2023_01:CODIGO_FAMILIA:51','mayalex_normativos','03_FAMILIA','También puede solicitar el reconocimiento de la unión de hecho una sola de las partes, ya sea por existir oposición o por haber muerto la otra, en cuyos casos deberá presentarse el interesado ante el Juez competente, quien en sentencia hará la declaración de la unión de hecho, si hubiere sido plenamente probada. En dicha declaración fijará el Juez, el día o fecha probable en que la unión dio principio, los hijos procreados y los bienes adquiridos durante ella.

En caso de fallecimiento la demanda se entablará contra los herederos y en defecto de éstos contra el pariente o parientes más próximos del fallecido.

La certificación de la sentencia favorable al demandante deberá presentarse al Registrador Civil y al Registro de la Propiedad Inmueble y Mercantil si hubiere bienes inmuebles, para que se proceda a las respectivas inscripciones.','51','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":51,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"f68457d3e91eb955c82c24dc5808c816087e5da789e1d6fdd77d0ece9a6722dd","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:51","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','51','f68457d3e91eb955c82c24dc5808c816087e5da789e1d6fdd77d0ece9a6722dd','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:52','mayalex_normativos','03_FAMILIA','La acción a la que se refiere el Artículo anterior deberá iniciarse antes de que transcurra un (1) año a partir de la fecha en que haya cesado la unión o haya ocurrido la muerte del otro conviviente.','52','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":52,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"a610831b1199e455d161ecebe56f061e1c1d6e5a6a33422b85d9f778aebde19a","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:52","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','52','a610831b1199e455d161ecebe56f061e1c1d6e5a6a33422b85d9f778aebde19a','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:53','mayalex_normativos','03_FAMILIA','La mujer de que a sabiendas de que el varón tiene registrada su unión de hecho con otra mujer, y el hombre que a sabiendas de que la mujer tiene registrada su unión de hecho con otro hombre, hicieren vida común, no gozarán de la protección de la Ley, mientras la unión registrada no hubiere sido disuelta legalmente y liquidados los bienes comunes.','53','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":53,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"34ea5087dea5a13958cf43896201ab3a4a0f5e8b5f0b00c140261261ecfee1a3","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:53","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','53','34ea5087dea5a13958cf43896201ab3a4a0f5e8b5f0b00c140261261ecfee1a3','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:54','mayalex_normativos','03_FAMILIA','En el caso de que varias mujeres igualmente solteras demandaren la declaración de la unión de hecho con el mismo hombre soltero, el Juez hará la declaración únicamente a favor de aquella que probare los extremos previstos en el artículo 53 y en igualdad de circunstancias, la declaración se hará en favor de la unión más antigua. Lo dispuesto en este Artículo es aplicable siempre que las uniones de hecho que se pretenda se declaren, coexistan en el momento de solicitarse la declaratoria respectiva o bien en la fecha en que incurrió la muerte de la persona con quien se mantuvo la unión de hecho.','54','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":54,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"76e8ac45b085692da0ea49c93d5ceac71e397212b2ecd10a976fc352ffb060ee","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:54","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','54','76e8ac45b085692da0ea49c93d5ceac71e397212b2ecd10a976fc352ffb060ee','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:55','mayalex_normativos','03_FAMILIA','La unión de hecho inscrita por el Registrador Civil produce los efectos siguientes:

1) Los hijos nacidos después de ciento cincuenta (150) días de la fecha fijada como principio de la unión de hecho y los nacidos dentro de los trescientos (300) días siguientes al día en que la unión cesó, se reputan hijos del varón con quien la madre estuvo unida, presunción contra la cual se admiteprueba en contrario;

2) Si no hubiere escritura de separación de bienes, los adquiridos durante la unión de hecho se reputan bienes de ambos, salvo prueba en contrario que demuestre que el bien fue adquirido por (1) un solo de ellos a título gratuito, o con el valor o por permuta de otro bien de su exclusiva propiedad;

3) Derecho de una de las partes a solicitar la declaratoria de ausencia de la otra y, una vez declarada, pedir la cesación de su unión con el ausente, liquidación del haber común y adjudicación de los bienes que le correspondan;

4) En caso de fallecimiento de alguno de ellos, el sobreviviente puede pedir la liquidación del haber común y adjudicación de bienes, al igual que en el caso del numeral anterior; y,

5) Sujeción del hombre y la mujer a los derechos y obligaciones de los cónyuges durante el matrimonio.','55','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":55,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"137086ace4cfc3cb2299627bef152e97c2164d053fc12283362e39f44109f349","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:55","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','55','137086ace4cfc3cb2299627bef152e97c2164d053fc12283362e39f44109f349','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:56','mayalex_normativos','03_FAMILIA','La unión de hecho puede cesar por mutuo acuerdo en la misma forma que se constituyó o por cualquiera de las causas señaladas en el divorcio y la separación, en cuyo caso la cesación deberá ser declarada judicialmente.

La cesación de la unión de hecho por mutuo acuerdo, deberá hacerse constar ante el Juez competente del domicilio de los convivientes, pero para que se reconozca y se ordene la anotación respectiva al Registrador Civil, debe cumplirse previamente con lo que dispone este Código, con respecto al divorcio de los cónyuges.','56','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":56,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"4829013abac239c30058b27c0075bd0b63f989e8c11d5c7313b2fdf2920e4cf5","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:56","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','56','4829013abac239c30058b27c0075bd0b63f989e8c11d5c7313b2fdf2920e4cf5','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:57','mayalex_normativos','03_FAMILIA','El varón y la mujer cuya unión de hecho consta en forma legal, se heredan recíprocamente ab-intestato en los mismos casos que para los cónyuges determina este Código.

Las disposiciones de este Código relativas a los deberes y derechos que nacen del matrimonio y el régimen económico de éste, tienen validez para las uniones de hecho, en lo que fueren aplicables.','57','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":57,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"2d4948e292ea96a9e180f12bf025ccc68dec6f7afd1f10de12413af25011f221","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:57","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','57','2d4948e292ea96a9e180f12bf025ccc68dec6f7afd1f10de12413af25011f221','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:58','mayalex_normativos','03_FAMILIA','Terminadas las diligencias de la cesación de la unión y satisfechas las exigencias legales, la autoridad que haya intervenido en ellas o el Notario que autorice la escritura de separación, liquidación y adjudicación de bienes, dará aviso al Registrador Civil que inscribió la unión de hecho, para que se haga la anotación correspondiente. La contravención a este Artículo será sancionada con una multa de Diez (10) Lempiras.','58','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":58,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"7f3eef7727602de9eb2e4d668a3f606750730bb1929a8f8a9a4cc045d9c49901","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:58","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','58','7f3eef7727602de9eb2e4d668a3f606750730bb1929a8f8a9a4cc045d9c49901','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:59','mayalex_normativos','03_FAMILIA','La separación una vez registrada, deja libres de estado a hombre y mujer, pero sin que esto perjudique las obligaciones que ambos tienen que cumplir con respecto a los hijos, quienes conservarán íntegros sus derechos a ser alimentados, no obstante, cualquier estipulación de los padres.','59','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":59,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"9eb31448cc6760de69b3f51700306667a219e3458612fb009120cdd9de5e5822","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:59","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','59','9eb31448cc6760de69b3f51700306667a219e3458612fb009120cdd9de5e5822','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:60','mayalex_normativos','03_FAMILIA','Para que pueda autorizarse el matrimonio de cualquiera de los dos (2) que haya hecho vida común que estuviere registrado, es indispensable que se proceda cumplir con lo preceptuado en el Artículo 48.','60','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":60,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"ee26517b6e5353d1b86c25c5aded2ec14793b63f907f7c605c498506d41e5448","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:60","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','60','ee26517b6e5353d1b86c25c5aded2ec14793b63f907f7c605c498506d41e5448','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:61','mayalex_normativos','03_FAMILIA','A la unión de hecho puede oponerse parte interesada para exigir que previamente se resuelvan cuestiones pendientes y se liquiden los bienes comunes.

El funcionario que intervenga en el matrimonio, no podrá autorizarlo si el solicitante no comprueba haber liquidado los bienes comunes y asegurados la prestación de alimentos de los hijos.','61','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":61,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"54d95e88418882a1a2cbeeb28b4ce7d617a14dccd6d1905cac7e9b339ddf75d7","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:61","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','61','54d95e88418882a1a2cbeeb28b4ce7d617a14dccd6d1905cac7e9b339ddf75d7','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:62','mayalex_normativos','03_FAMILIA','Para que la unión de hecho pueda ser formalizada es necesario que las personas hayan hecho vida en común por un lapso continuó no menor de (3) tres años.

No obstante, si antes de ese período hubieren procreado hijos se podrá formalizar la unión de hecho por cualquiera de las modalidades previstas en este Título, siempre que se cumplieren los requisitos establecidos en este Código.','62','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":62,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"de63ba2177d44e5ff3ab8d1ea5189d7550f1614b609448c7c7e2a92c88beaabb","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:62","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','62','de63ba2177d44e5ff3ab8d1ea5189d7550f1614b609448c7c7e2a92c88beaabb','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:63','mayalex_normativos','03_FAMILIA','Cuando la unión de hecho que se demanda fuese irregular porque uno de los convivientes esté casado o tenga unión de hecho formalizada con otra persona, dicha situación irregular no podrá ser formalizada, pero sí producirá efectos respecto del conviviente de buena fe de la unión irregular y de los hijos procreados.','63','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":63,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"ca683c1385fdd35992823c05cc8504b7e4618c9f5788667bfd7ca966c6d6f4e6","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:63","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','63','ca683c1385fdd35992823c05cc8504b7e4618c9f5788667bfd7ca966c6d6f4e6','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:64','mayalex_normativos','03_FAMILIA','El régimen económico del matrimonio se podrá regular por el sistema de comunidad de bienes, sociedad ganancial, separación de bienes, sin excluir en ninguno de ellos la formación del patrimonio familiar.','64','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":64,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"040eaa916781686911c822cd777070a19011c5876f77e900570a21fa7929f320","ubicacion":["CAPÍTULO VI","DEL RÉGIMEN ECONÓMICO"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:64","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','64','040eaa916781686911c822cd777070a19011c5876f77e900570a21fa7929f320','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:65','mayalex_normativos','03_FAMILIA','Los futuros esposos pueden antes de celebrar su matrimonio, arreglar todo lo que se refiera a sus bienes presentes y futuros; para tal fin, deben celebrarse capitulaciones matrimoniales.','65','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":65,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"f072d5c8b9a49ad9dbcfa7ce74d6e64bfd68617bed637191bc98bc08b488e6be","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:65","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','65','f072d5c8b9a49ad9dbcfa7ce74d6e64bfd68617bed637191bc98bc08b488e6be','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:66','mayalex_normativos','03_FAMILIA','El menor hábil para casarse puede celebrar capitulaciones matrimoniales por medio de la persona cuyo consentimiento sea necesario para contraer matrimonio.','66','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":66,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"55c8069b18da807018e997c0b35d3bf8b80058420bd6b094aa0329e58f7f38ae","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:66","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','66','55c8069b18da807018e997c0b35d3bf8b80058420bd6b094aa0329e58f7f38ae','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:67','mayalex_normativos','03_FAMILIA','Las capitulaciones matrimoniales pueden alterarse después de celebrado el matrimonio, pero el cambio no perjudicará a terceros posteriores a él, sino después que la nueva escritura esté inscrita en el Registro respectivo, y que se haya anunciado en el Diario oficial "La Gaceta" que los cónyuges han alterado sus capitulaciones.','67','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":67,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"8a6e5f8cfdaeccd0cda42b642d78b34dcfc95617823033fb35aa5fc0f5f08b1c","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:67","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','67','8a6e5f8cfdaeccd0cda42b642d78b34dcfc95617823033fb35aa5fc0f5f08b1c','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:68','mayalex_normativos','03_FAMILIA','A falta de capitulaciones matrimoniales, el régimen económico por el cual se regirá el vínculo, será el de la sociedad ganancial.','68','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":68,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"27700ef113f16452146c1ff9839a04e91cfceb9873052be681684ea0b0546ec9","ubicacion":[],"constancias":[{"nota":7,"tipo":"REFORMA","texto":"Artículo 68. Reformado mediante Decreto 31-2015, del 7 de abril de 2015. Publicado en el Diario Oficial La Gaceta No.33,799 de fecha 4 de agosto de 2015.","decretos":["31-2015"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":"v2familia:mayalex_normativos:68","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (reforma integrada): edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','68','27700ef113f16452146c1ff9839a04e91cfceb9873052be681684ea0b0546ec9','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:69','mayalex_normativos','03_FAMILIA','Aquellos bienes que a la disolución del matrimonio no hubieren sido repartidos, no podrán ser arrendados por más de cinco (5) años, ni enajenados, ni gravados, sin el consentimiento del otro cónyuge y si fueren perseguidos por acreedores personales sólo podrán ser adjudicados o subastados en la mitad de su valor, considerándose desde ese momento que la otra mitad le pertenece al cónyuge no accionado.','69','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":69,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"8b4bd25eddf5e5fb2d29f6db98fac875fbaf2b0af703599ecb700aef13f8fb46","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:69","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','69','8b4bd25eddf5e5fb2d29f6db98fac875fbaf2b0af703599ecb700aef13f8fb46','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:70','mayalex_normativos','03_FAMILIA','Mediante la sociedad ganancial se hacen comunes para los cónyuges cada uno de los bienes muebles o inmuebles obtenidos a título oneroso, indistintamente por cualquiera de ellos durante el matrimonio, los cuales les serán repartidos por la mitad en caso de disolverse el vínculo matrimonial. Se exceptúan los bienes muebles e inmuebles adquiridos a título gratuito y los considerados menajes del hogar, los cuales quedarán a favor de la mujer tal como lo establece el “Artículo 72 de este Código.','70','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":70,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"8f9e663fed758ac9b8276ea680cd920f1434458110d81dd8cf926f3f593420eb","ubicacion":[],"constancias":[{"nota":8,"tipo":"REFORMA","texto":"Artículo 70. Reformado mediante Decreto 31-2015, del 7 de abril de 2015. Publicado en el Diario Oficial La Gaceta No.33,799 de fecha 4 de agosto de 2015.","decretos":["31-2015"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":"v2familia:mayalex_normativos:70","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (reforma integrada): edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','70','8f9e663fed758ac9b8276ea680cd920f1434458110d81dd8cf926f3f593420eb','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:70-A','mayalex_normativos','03_FAMILIA','Son bienes privativos o propios de cada uno de los cónyuges:

1) Los bienes y derechos que le pertenecieran antes de la sociedad ganancial a todos aquellos cuya causa o título de adquisición precedió al matrimonio, conforme a lo declarado en la respectiva declaración jurada de bienes;

2) Los que adquiera después a título gratuito.
3) Los adquiridos a costa o en sustitución de bienes propios;
4) Los bienes y derechos patrimoniales adquiridos mediante herencia y/o legados;
5) El resarcimiento por daños referidos a la persona de uno de los cónyuges o a sus bienes privativos;
6) La ropa, objetos y accesorios de uso personal; y,
7) Los instrumentos u objetos de uso indispensable para el ejercicio de la profesión u oficio, salvo cuando éstos sean parte integrante o pertenencias de una empresa de carácter común.

Los bienes relacionados en el numeral 7) no perderán su carácter de bienes propios por el hecho de que su adquisición se haya realizado con fondos comunes; pero, en este caso, la sociedad ganancial constituida será acreedora del cónyuge propietario por el valor satisfecho.','70-A','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":71,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"d1c553c6cde6cd2a7fe264a9bbd4a52552f02903c8acfb1765966cc3080c7bd6","ubicacion":[],"constancias":[{"nota":9,"tipo":"ADICION","texto":"Artículo 70-A. Adicionado mediante Decreto 31-2015, del 7 de abril de 2015. Publicado en el Diario Oficial La GacetaNo.33,799 de fecha 4 de agosto de 2015.","decretos":["31-2015"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (artículo adicionado): edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','70-A','d1c553c6cde6cd2a7fe264a9bbd4a52552f02903c8acfb1765966cc3080c7bd6','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:70-B','mayalex_normativos','03_FAMILIA','Constituyen bienes gananciales:

1) Los obtenidos por el trabajo o la industria de cualquiera de los cónyuges;
2) Los frutos, rentas o intereses que produzcan tanto los bienes propios como los bienes gananciales;
3) Los adquiridos a título oneroso a costa del caudal común, bien se haga la adquisición en común, bien para uno solo de los cónyuges; y,
4) Las empresas fundadas durante la vigencia de la sociedad ganancial por uno o cualquiera de los cónyuges a expensas de los bienes comunes.

Se presumen gananciales los bienes existentes en el matrimonio mientras no se pruebe que pertenecen privativamente a uno de los cónyuges.','70-B','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":72,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"66c51411426adf42159ed9fda148d1337be0ea0ea3816afb4a4d18dea843e3b2","ubicacion":[],"constancias":[{"nota":10,"tipo":"ADICION","texto":"Artículo 70-B. Adicionado mediante Decreto 31-2015, del 7 de abril de 2015. Publicado en el Diario Oficial La GacetaNo.33,799 de fecha 4 de agosto de 2015","decretos":["31-2015"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (artículo adicionado): edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','70-B','66c51411426adf42159ed9fda148d1337be0ea0ea3816afb4a4d18dea843e3b2','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:70-C','mayalex_normativos','03_FAMILIA','La sociedad ganancial empezará en el momento de la celebración del matrimonio o posterior al tiempo de pactarse en capitulaciones matrimoniales debidamente inscritas en el Registro Público correspondiente.','70-C','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":73,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"fb01f192bf72b93e0e75c11e8a9f02fa705f188b763b1a8df9e3f55515ab5108","ubicacion":[],"constancias":[{"nota":11,"tipo":"ADICION","texto":"Artículo 70-C. Adicionado mediante Decreto 31-2015, del 7 de abril de 2015. Publicado en el Diario Oficial La GacetaNo.33,799 de fecha 4 de agosto de 2015","decretos":["31-2015"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (artículo adicionado): edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','70-C','fb01f192bf72b93e0e75c11e8a9f02fa705f188b763b1a8df9e3f55515ab5108','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:70-D','mayalex_normativos','03_FAMILIA','Se procederá a la liquidación de la sociedad ganancial garantizando ambos cónyuges, en primer lugar, los derechos ya reconocidos a los hijos e hijas menores de edad o que se encuentren en las condiciones señaladas en el Artículo 211 de este Código, con especial atención a la obligación degarantizar el cumplimiento de derechos de la niñez reconocidos en la Constitución de la República, Código de la Niñez y la Adolescencia, el presente Código y demás leyes aplicables.

Para este efecto, se establece que el inmueble destinado a habitación familiar, no entrará en liquidación de la sociedad ganancial, sino que se constituirá usufructo a favor del cónyuge que quede responsable de la guardia y custodia de los hijos e hijas menores, hasta que éstos adquieran su mayoría de edad, sin perjuicio de lo dispuesto en el Artículo 217 numeral 6) de este Código; este usufructo podrá ser vitalicio cuando se trate de hijas e hijos con incapacidades permanentes en ambos casos el usufructo se disolverá al desaparecer las causas de su constitución. Tampoco podrá ser enajenado ni gravado sino con el consentimiento de ambos cónyuges o por disposición judicial a solicitud de cualquiera de los cónyuges; previa demostración, en este último caso, de la utilidad y la necesidad debidamente justificada de dicho acto.

Durante la vigencia de la sociedad ganancial los cónyuges no podrán ocultar bienes o cometer fraude de cualquier tipo sobre los mismos. De igual manera no podrán gravarse o donarse ni enajenarse de ninguna forma sin el consentimiento de ambos cónyuges.','70-D','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":74,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"c69be4494316ebf717b30227418452f70d720e78cc560d40516ace2f8a1eb00e","ubicacion":[],"constancias":[{"nota":12,"tipo":"ADICION","texto":"Artículo 70-D. Adicionado mediante Decreto 31-2015, del 7 de abril de 2015. Publicado en el Diario Oficial La GacetaNo.33,799 de fecha 4 de agosto de 2015","decretos":["31-2015"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (artículo adicionado): edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','70-D','c69be4494316ebf717b30227418452f70d720e78cc560d40516ace2f8a1eb00e','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:71','mayalex_normativos','03_FAMILIA','La separación absoluta de bienes no exime en ningún caso a los cónyuges de la obligación común de sostener los gastos del hogar, la alimentación y educación de los hijos, las demás cargas del matrimonio y la conservación del patrimonio familiar.','71','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":75,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"e3c60345e42270f4e1e3f969f1b8d674436cddbe36066172dc8276515805a73a","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:71","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','71','e3c60345e42270f4e1e3f969f1b8d674436cddbe36066172dc8276515805a73a','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:72','mayalex_normativos','03_FAMILIA','Corresponde exclusivamente a la mujer el menaje del hogar conyugal, exceptuándose únicamente los objetos de uso personal del marido.','72','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":76,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"f1c6daf4e5e0dccdd7821fc93bf1a432b5ca0367550c39e0241b859e80982b12","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:72","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','72','f1c6daf4e5e0dccdd7821fc93bf1a432b5ca0367550c39e0241b859e80982b12','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:73','mayalex_normativos','03_FAMILIA','De las obligaciones que contraiga cualquiera de los cónyuges para el sostenimiento de la familia responderán los bienes comunes y si éstos fueren insuficientes, los bienes propios de cada uno de ellos.','73','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":77,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"6beb3cf4129193ffab4c47d2af0ae97bb98f207ff549d73d954b23c2b6e8edb1","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:73","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','73','6beb3cf4129193ffab4c47d2af0ae97bb98f207ff549d73d954b23c2b6e8edb1','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:74','mayalex_normativos','03_FAMILIA','La responsabilidad civil por hechos ilícitos de un cónyuge, no obliga al otro en sus bienes propios ni en su parte de los comunes.','74','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":78,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"f40deabc97fe5a74ec2e83daa71591940e7c51e3134ddad9ec52169e175674a1","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:74","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','74','f40deabc97fe5a74ec2e83daa71591940e7c51e3134ddad9ec52169e175674a1','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:75','mayalex_normativos','03_FAMILIA','Las deudas anteriores al matrimonio serán pagadas con los bienes propios del que las contrajo, aun cuando aquél se rija por el régimen de comunidad.','75','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":79,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"f71aba8153415bd6d4d60f64b2bee0183900086aab751afd8cfae4021ceaece6","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:75","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','75','f71aba8153415bd6d4d60f64b2bee0183900086aab751afd8cfae4021ceaece6','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:76','mayalex_normativos','03_FAMILIA','Los gastos que causaren las enfermedades, así como los que se originen por funerales a consecuencia de la muerte de un cónyuge o de los hijos de ambos, se reputan deudas comunes del matrimonio, por las cuales son responsables los bienes propios de los cónyuges, en el caso de ser insuficientes los comunes.','76','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":80,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"874f700a3501fb882b41d8c759d356e1ede6c11e79cd6caae2ec21a84f03d02e","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:76","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','76','874f700a3501fb882b41d8c759d356e1ede6c11e79cd6caae2ec21a84f03d02e','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:77','mayalex_normativos','03_FAMILIA','La comunidad de bienes termina:

1) Por la disolución del matrimonio;
2) Por separación de bienes; y
3) Por ser condenado en sentencia judicial firme alguno de los cónyuges por delito cometido en contra del otro.','77','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":81,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"aacc557e343cbbc44e57ba5e560e8186076896f92a607646e40ef6508369de57","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:77","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','77','aacc557e343cbbc44e57ba5e560e8186076896f92a607646e40ef6508369de57','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:78','mayalex_normativos','03_FAMILIA','El abandono injustificado del hogar conyugal por uno de los cónyuges, hace cesar para él, desde el día del abandono, los efectos de la comunidad de bienes en cuanto le favorezcan.','78','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":82,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"bfdc1630e63e77fa590ddacf8a0f803671afe834e95813ac29ad98ad56374247","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:78","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','78','bfdc1630e63e77fa590ddacf8a0f803671afe834e95813ac29ad98ad56374247','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:79','mayalex_normativos','03_FAMILIA','En caso de separación de hecho, el cónyuge culpable no tendrá derecho a gananciales durante el tiempo de la separación.','79','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":83,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"1790e65324b4129a317a328f3425bab7a578978a89803180c641417ef8adee55","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:79","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','79','1790e65324b4129a317a328f3425bab7a578978a89803180c641417ef8adee55','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:80','mayalex_normativos','03_FAMILIA','Cuando se declare la nulidad del matrimonio, el cónyuge que hubiere obrado de mala fe no tendrá participación en los bienes de la comunidad matrimonial, cuando procediere.','80','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":84,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"cbeced3baaa3e5fff1f9db92515dd3cf029b4e352dc6d6fd419e52ae27029f0e","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:80","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','80','cbeced3baaa3e5fff1f9db92515dd3cf029b4e352dc6d6fd419e52ae27029f0e','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:81','mayalex_normativos','03_FAMILIA','Los cónyuges son los administradores de la comunidad conyugal y cualquiera de ellos podrá realizar indistintamente los actos de administración o por mutuo acuerdo nombrar a uno de ellos como administrador.

No obstante, lo dispuesto en este Artículo, el otro cónyuge podrá oponerse a cualquier acto que redundare en perjuicio de los intereses de la comunidad y hacer cesar la administración, con separación de bienes, cuando por notorianegligencia o incapacidad el administrador amenazare destruir el patrimonio común o no proveyere al adecuado mantenimiento.','81','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":85,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"a9345b303fbaca734865f3751d6cb57513e42bbd59f3f472a0aff8ac9d89b5ab","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:81","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','81','a9345b303fbaca734865f3751d6cb57513e42bbd59f3f472a0aff8ac9d89b5ab','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:82','mayalex_normativos','03_FAMILIA','El patrimonio familiar es la institución jurídico-social por medio de la cual se destina uno o más bienes a la protección del hogar y sostenimiento de la familia.','82','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":86,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"2d614a1fbbe9821b33e0f3bc01c8419789d6a91166e0f53fca19f263a7acf22e","ubicacion":["CAPÍTULO VII","DEL PATRIMONIO FAMILIAR"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:82","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','82','2d614a1fbbe9821b33e0f3bc01c8419789d6a91166e0f53fca19f263a7acf22e','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:83','mayalex_normativos','03_FAMILIA','El patrimonio familiar deberá fijarse de conformidad con la capacidad económica de los contrayentes.','83','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":87,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"9d73ed6963390438e29fdfdf0c208964931743f6098bb7527b46861785e5a95e","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:83","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','83','9d73ed6963390438e29fdfdf0c208964931743f6098bb7527b46861785e5a95e','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:84','mayalex_normativos','03_FAMILIA','Las casas de habitación, los predios o parcelas cultivables, los establecimientos industriales y comerciales, que sean objeto de explotación familiar, pueden constituir el patrimonio de la familia, siempre que su valor no exceda de la cantidad máxima fijada en este Capítulo.','84','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":88,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"8efbc9e1936b1db08e0f3afc8525bbcf5932b094c35a307e4178726ea8ac8b08","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:84","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','84','8efbc9e1936b1db08e0f3afc8525bbcf5932b094c35a307e4178726ea8ac8b08','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:85','mayalex_normativos','03_FAMILIA','Sólo puede fundarse un patrimonio para cada familia, por el padre o la madre sobre los bienes propios, o por el marido o mujer sobre bienes comunes de la sociedad conyugal. También puede constituirse por un tercero a título de donación o legado o por mandato de Juez(a) competente cuando lo considere oportuno en procura de la protección del interés superior de los hijos e hijas.','85','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":89,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"GACETA_33222_D35_2013","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"615f6cb1e6cb5f2375bb8e4db924d7c58120685bad1d4ae0690817d27c4c9294","ubicacion":[],"constancias":[{"nota":13,"tipo":"REFORMA","texto":"Artículo 85. Reformado mediante Decreto 35-2013, del 27 de febrero de 2013. Publicado en el Diario Oficial La GacetaNo.33,222 de fecha 6 de septiembre de 2013.","decretos":["35-2013"]},{"nota":null,"tipo":"TEXTO_OFICIAL_GACETA","decretos":["35-2013"],"texto":"Texto tomado del D.35-2013 (La Gaceta No. 33,222), que coincide en sustancia con la edición CEDIJ (similitud 0.977); sha256 del texto de la edición: e3cf17670742d13db44cc750865168ab19081f1e5372b09da414bcc4be9195b3."}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS","TEXTO_OFICIAL_GACETA"],"sustituye_id_legacy":"v2familia:mayalex_normativos:85","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY: texto oficial del D.35-2013 (Gaceta 33,222)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','85','615f6cb1e6cb5f2375bb8e4db924d7c58120685bad1d4ae0690817d27c4c9294','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:86','mayalex_normativos','03_FAMILIA','Los bienes constituidos en patrimonio familiar no excederán de UN MILLÓN DE LEMPIRAS (L. 1,000,000.00) y son indivisibles, inalienables, inembargables y no podrán estar gravados ni gravarse, salvo el caso de servidumbre legal y judicial.

La referida cantidad será ajustada por el(la) Juez(a) competente con base al índice de inflación vigente.

Sin embargo, el(la) Juez(a) competente puede autorizar la venta o gravamen de un bien constituido como patrimonio familiar, siempre que se cumpla con todos los requisitos siguientes:

1. Signifique un incremento en el patrimonio originalmente constituido; 2. Se acredite que el producto de la venta será constituido como patrimonio familiar; 3. El nuevo patrimonio sea de iguales o mejores condiciones del originalmente constituido, de manera que se garantice el derecho de los(las) beneficia- rios(as); 4. En el caso que el producto de la venta supere el techo establecido para la constitución de un patrimonio, el excedente será invertido preferentemente en provecho de los(las) beneficiarios(as) del mismo, sin que se pueda destinar a tal fin un porcentaje menor al cincuenta por ciento (50%); y, 5. Venta o gravamen por causas de necesidad extrema, debidamente acreditadas ante el(la) Juez(a) competente, quien la autorizará.','86','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":90,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"GACETA_33222_D35_2013","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"2b0a783e533a48409b7c0f4d93e607a5c7395ffd3d6a0a1a1f402f78fa69de12","ubicacion":[],"constancias":[{"nota":14,"tipo":"REFORMA","texto":"Artículo 86. Reformado mediante Decreto 35-2013, del 27 de febrero de 2013. Publicado en el Diario Oficial La GacetaNo.33,222 de fecha 6 de septiembre de 2013.","decretos":["35-2013"]},{"nota":null,"tipo":"TEXTO_OFICIAL_GACETA","decretos":["35-2013"],"texto":"Texto tomado del D.35-2013 (La Gaceta No. 33,222), que coincide en sustancia con la edición CEDIJ (similitud 0.943); sha256 del texto de la edición: 730c80f16226ed64bb8d981312b9b3beadcffb730baaf8227fd14120329d2fc2."}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS","TEXTO_OFICIAL_GACETA"],"sustituye_id_legacy":"v2familia:mayalex_normativos:86","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY: texto oficial del D.35-2013 (Gaceta 33,222)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','86','2b0a783e533a48409b7c0f4d93e607a5c7395ffd3d6a0a1a1f402f78fa69de12','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:87','mayalex_normativos','03_FAMILIA','El establecimiento del patrimonio familiar no puede hacerse en fraude de acreedores. Los bienes deben estar libres de anotación y gravamen y lagestión del instituyente solicitando la aprobación judicial, será publicada en el

Diario Oficial "La Gaceta", para que llegue a conocimiento de los que puedan tener interés en oponerse.','87','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":91,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"cd3638202a244c3b85d4cc9f637a87e4c850fada083918b845e0a9a901a2fced","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:87","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','87','cd3638202a244c3b85d4cc9f637a87e4c850fada083918b845e0a9a901a2fced','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:88','mayalex_normativos','03_FAMILIA','Los miembros de la familia beneficiaria están obligados a habitar la casa y a laborar en el predio agrícola, la industria o negocio establecido enbeneficio de la misma, salvo las excepciones que el Juez competente permita temporalmente por motivos justificados.','88','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":92,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"22f31f9ec94f26cfc6fa38419eeccab6c7f21df6091b914d86af82756880317b","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:88","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','88','22f31f9ec94f26cfc6fa38419eeccab6c7f21df6091b914d86af82756880317b','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:89','mayalex_normativos','03_FAMILIA','Si el inmueble constituido en patrimonio familiar fuere inscrito únicamente a nombre del cabeza de familia, se entenderá que ha sido constituido para el sostenimiento del cónyuge, de los hijos menores o incapaces y de las personas que tengan derechos a ser alimentados por aquél.','89','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":93,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"5f467f98179a98c9087c5da48e0fd791c39ca8f377dd6d22ad063b7ed8b14c6f","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:89","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','89','5f467f98179a98c9087c5da48e0fd791c39ca8f377dd6d22ad063b7ed8b14c6f','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:90','mayalex_normativos','03_FAMILIA','Cuando haya peligro de que la persona que tiene obligación de dar alimentos, pierda sus bienes por mala administración o porque los esté dilapidando, los acreedores por concepto de alimentos, tienen derecho a exigir judicialmente que se constituya patrimonio familiar sobre determinado bien del obligado.','90','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":94,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"43bae28fa6bb64db86bf7a7369d5fae1ea90d9375bec75684f36e425d7327d38","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:90","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','90','43bae28fa6bb64db86bf7a7369d5fae1ea90d9375bec75684f36e425d7327d38','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:91','mayalex_normativos','03_FAMILIA','Para la constitución del patrimonio familiar se requiere la aprobación judicial y su inscripción en el Registro de la Propiedad Inmueble y Mercantil, previos los trámites legales correspondientes.

Sin embargo, cuando el Estado procede al parcelamiento y distribución de un bien nacional, podrá darle a cada parcela el carácter de patrimonio familiar y bastará esa calificación legal para su constitución y registro. En lo demás, este patrimonio familiar se regulará de conformidad con lo dispuesto en este Código en todo lo que le sea aplicable.','91','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":95,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"ac2200fdb593121a1a51ff5edf3e27ebbea2f6e36fffbeb0dad520f1e6f81e66","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:91","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','91','ac2200fdb593121a1a51ff5edf3e27ebbea2f6e36fffbeb0dad520f1e6f81e66','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:92','mayalex_normativos','03_FAMILIA','El representante legal de la familia será el administrador del patrimonio familiar y representante a la vez de los beneficiarios en todo lo que al patrimonio se refiere.','92','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":96,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"db2253b2403c7a2241cd591825d30eea40748849bbecdd017b89b113d88a8110","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:92","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','92','db2253b2403c7a2241cd591825d30eea40748849bbecdd017b89b113d88a8110','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:93','mayalex_normativos','03_FAMILIA','El patrimonio familiar termina:

1) Cuando todos los beneficiarios cesen de tener derecho a percibir alimentos;
2) Cuando sin causa justificada y sin autorización judicial, la familia deje dehabitar la casa que debe servirle de morada, o de cultivar por su cuenta la parcela o predio vinculado;
3) Cuando se demuestre la utilidad y necesidad para la familia, de que el patrimonio quede extinguido;
4) Cuando por causa de utilidad pública se expropien los bienes que lo forman, previa indemnización; y
5) Por vencerse el término por el cual fue constituido.','93','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":97,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"4ddfb0f1a16d7de2314a1b98cc1e53db3960271f133d679695115d6b572529da","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:93","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','93','4ddfb0f1a16d7de2314a1b98cc1e53db3960271f133d679695115d6b572529da','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:94','mayalex_normativos','03_FAMILIA','El patrimonio familiar a término fijo, debe comprender el término indispensable para que el menor de los miembros actuales de la familia alcance la mayoría de edad, pero en ningún caso podrá constituirse un patrimonio familiar por un término menor de quince (15) años.','94','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":98,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"4cefe45d5b11792ea4466c800fe60ff2429cfa53768c164d3deddf41a3ac6d7c","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:94","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','94','4cefe45d5b11792ea4466c800fe60ff2429cfa53768c164d3deddf41a3ac6d7c','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:95','mayalex_normativos','03_FAMILIA','Terminado el derecho al patrimonio familiar, los bienes sobre los que fue constituido, volverán al poder de quien lo constituyó o de sus herederos; pero si el dominio corresponde a los beneficiarios, tendrán derecho a hacer cesar la indivisión.','95','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":99,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"a98399e87487fe71a19e947b17f99c1d2e8774c942b1bb5139beb5ac36aac797","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:95","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','95','a98399e87487fe71a19e947b17f99c1d2e8774c942b1bb5139beb5ac36aac797','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:96','mayalex_normativos','03_FAMILIA','Cuando el patrimonio se extinga por expropiación del inmueble, la indemnización respectiva se depositará en una institución bancaria mientras se constituye un nuevo patrimonio familiar.','96','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":100,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"ea33f03ad095927d4b53438497c5498129c0f4717f731bfeedcaacbd23656da9","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:96","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','96','ea33f03ad095927d4b53438497c5498129c0f4717f731bfeedcaacbd23656da9','OLA5_CF_2023_01',now())
