INSERT INTO public.biblioteca_vectores (id,coleccion,materia,contenido,num_articulo,fuente,metadata,embedding,jurisdiccion,fuente_tipo,es_norma_vigente,revision_pendiente,instrumento_id,num_articulo_norm,hash_contenido,ingest_batch,ingested_at) VALUES
('OLA5_CF_2023_01:CODIGO_FAMILIA:261','mayalex_normativos','03_FAMILIA','Los hijos de las personas a que se refiere este Capítulo, podrán hasta (2) dos años después de haber alcanzado la mayoría de edad, exigir daños y perjuicios a las personas que hubieren declarado o testificado la no existencia de bienes o participado en la facción de inventario y tasación de bienes, si se llegare a probar que por descuido o mala fe, se omitió o se hizo incorrectamente.','261','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":301,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"0488e244b323e90bb3c1c0ddc5ab9912500b94774e23431fed7c3d5613780f1a","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:261","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','261','0488e244b323e90bb3c1c0ddc5ab9912500b94774e23431fed7c3d5613780f1a','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:262','mayalex_normativos','03_FAMILIA','No será motivo de pérdida de la patria potestad o guarda de los hijos, para aquellos padres que la ejerzan, el contraer segundas o ulteriores nupcias.','262','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":302,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"51728d2d8f75d69f5ebc48d2e9f4dc97da88949b3611e04cee95ab3eeaebf1fc","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:262","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','262','51728d2d8f75d69f5ebc48d2e9f4dc97da88949b3611e04cee95ab3eeaebf1fc','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:263','mayalex_normativos','03_FAMILIA','El menor de edad que no se halle bajo la patria potestad, quedará sujeto a tutela para el cuidado de su persona y de sus bienes. También quedará sujeto a tutela, aunque fuere mayor de edad, el que hubiere sido declarado en estado de interdicción, sino hubiere padres.

El tutor es el representante legal del menor o incapacitado.','263','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":303,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"5ab567784de18a051f5dce01fca42268e2a1b691060aea3a5d9d9ffb42a6bc3f","ubicacion":["TÍTULO","VIII DE LA","TUTELA","CAPÍTULO I","DE LAS DISPOSICIONES GENERALES"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:263","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','263','5ab567784de18a051f5dce01fca42268e2a1b691060aea3a5d9d9ffb42a6bc3f','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:264','mayalex_normativos','03_FAMILIA','La tutela se ejerce por un tutor y un protutor, cuyos cargos son personales y son delegables, pero pueden otorgar mandatos especiales para actos determinados.','264','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":304,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"431cafdfdf2227176838b60aefb5ea31b6bdcdce94028037565fa4adc93742cc","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:264","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','264','431cafdfdf2227176838b60aefb5ea31b6bdcdce94028037565fa4adc93742cc','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:265','mayalex_normativos','03_FAMILIA','La tutela y pro tutela son cargos públicos a cuyo desempeño están obligadas todas las personas que se encuentren en pleno goce de sus derechos civiles.','265','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":305,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"175cc46b162a5fbd738e1c3bd0fb0897ecd2ff7b010ddc897d87b124cbc6be03","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:265","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','265','175cc46b162a5fbd738e1c3bd0fb0897ecd2ff7b010ddc897d87b124cbc6be03','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:266','mayalex_normativos','03_FAMILIA','La tutela puede ser testamentaria, legítima y judicial.','266','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":306,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"45c435a8b68cd046093ed136d19df525570feec4866e959630c01b4f496b217c","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:266","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','266','45c435a8b68cd046093ed136d19df525570feec4866e959630c01b4f496b217c','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:267','mayalex_normativos','03_FAMILIA','La tutela testamentaria se instituye en cualquiera de los siguientes casos:

1) Por el padre o la madre sobreviviente, para los hijos(as) que estén bajo su Patria Potestad;
2) Del padre al hijo(a) que se encuentre en el vientre materno, para el caso en que nazca vivo(a), y muera la madre sin nombrarle tutor(a);
3) Por el abuelo(a), para los nietos(as) que están bajo su tutela legítima;
4) Por cualquier testador, para el que instituya heredero o legatario; si éste careciere de tutor(a) nombrado(a) por el padre o la madre y de tutor legítimo; y,
5) Por el(la) adoptante o adoptantes que designe heredero(a) o legatario(a) a su hijo(a) adoptivo(a).','267','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":307,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"GACETA_33222_D35_2013","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"83ae254680aa33bbaa79066c502e51cf91ec7ee42d4f433b628055d3aa505bc4","ubicacion":[],"constancias":[{"nota":133,"tipo":"REFORMA","texto":"Artículo 267. Reformado mediante Decreto 35-2013, del 27 de febrero de 2013. Publicado en el Diario Oficial La Gaceta No. 33,222 de fecha 6 de septiembre de 2013.","decretos":["35-2013"]},{"nota":null,"tipo":"TEXTO_OFICIAL_GACETA","decretos":["35-2013"],"texto":"Texto tomado del D.35-2013 (La Gaceta No. 33,222), que coincide en sustancia con la edición CEDIJ (similitud 0.988); sha256 del texto de la edición: 8466e4682f5e179119e8e98da83f86fe79866cd779f0dc984a0ca705e9a88533."}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS","TEXTO_OFICIAL_GACETA"],"sustituye_id_legacy":"v2familia:mayalex_normativos:267","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY: texto oficial del D.35-2013 (Gaceta 33,222)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','267','83ae254680aa33bbaa79066c502e51cf91ec7ee42d4f433b628055d3aa505bc4','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:268','mayalex_normativos','03_FAMILIA','Los padres y los abuelos, en su caso, pueden nombrar un tutor para todos o para varios de sus hijos o para cada uno de ellos. Pueden también nombrar varios tutores y protutores para que ejerzan el cargo uno enefecto de otro, respectivamente, en el orden de su designación.','268','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":308,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"262fb5d8f4ef0637446c4e919b0003740509843ac5c51a7dba656602cf8b8c1b","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:268","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','268','262fb5d8f4ef0637446c4e919b0003740509843ac5c51a7dba656602cf8b8c1b','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:269','mayalex_normativos','03_FAMILIA','La tutela legítima de los menores corresponde en el orden siguiente:

1) Al abuelo paterno;
2) Al abuelo materno;
3) A la abuela paterna;
4) A la abuela materna; y,
5) A los hermanos del pupilo y a los tíos sin distinción de sexo, siendo preferidos los que procedan de ambas líneas y entre éstos el de mayor edad y capacidad.

La línea materna será preferida a la paterna para la tutela de los hijos fuera del matrimonio. Sin embargo, mediante motivos justificados para variar la procedencia, puede el Juez nombrar tutor al pariente que reúna las mejores condiciones de conocimiento y familiaridad con el menor, solvencia, idoneidad y preparación, que constituya una garantía para el desempeño satisfactorio de su cargo.','269','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":309,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"6980dfc0e1f076fed8bd0d39805d3cbf983f065229d7983e760c9a2a30184690","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:269","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','269','6980dfc0e1f076fed8bd0d39805d3cbf983f065229d7983e760c9a2a30184690','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:270','mayalex_normativos','03_FAMILIA','La tutela judicial procede por nombramiento del Juez competente cuando no haya tutor testamentario ni legítimo. Para ese efecto, el Ministerio Público y cualquier persona capaz deben denunciar a la autoridad el hecho que da lugar a la tutela prevista.

Para la designación de la persona del tutor, el Juez deberá tomar en cuenta las circunstancias que se mencionan en el Artículo anterior.','270','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":310,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"68aebc476fd4aa90bed368e13af730109bbde8af46445b316eebce49d09855f7","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:270","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','270','68aebc476fd4aa90bed368e13af730109bbde8af46445b316eebce49d09855f7','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:271','mayalex_normativos','03_FAMILIA','La tutela de los mayores de edad, declarados en interdicción, corresponde:

1) Al cónyuge;
2) Al padre y la madre;
3) A los hijos mayores de edad; y,
4) A los abuelos','271','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":311,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"7690177f069ed8ed24af7263c1cbd141cde4138ddce790b3eb665d790fc4c122","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:271","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','271','7690177f069ed8ed24af7263c1cbd141cde4138ddce790b3eb665d790fc4c122','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:272','mayalex_normativos','03_FAMILIA','Si hallándose en el ejercicio un tutor legítimo o judicial apareciere el testamentario, se transferirá inmediatamente a éste la tutela.','272','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":312,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"7199fa7fdd9be4c4d9ed4ed8714fa4e40571002bf6cdef9002458b4770f6bb9e","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:272","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','272','7199fa7fdd9be4c4d9ed4ed8714fa4e40571002bf6cdef9002458b4770f6bb9e','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:273','mayalex_normativos','03_FAMILIA','A los menores que hayan cumplido la edad de dieciséis (16) años, debe asociarlos el tutor en la administración de los bienes para su información y conocimiento, y si carecieren de tutor testamentario, tendrán derecho a proponer candidato entre sus parientes llamados a la tutela legítima, o a falta de éstos, a personas de reconocida honorabilidad para que ejerza la tutela judicial.','273','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":313,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"53ad01b53c0dc3c60374b7428597d1052362338be653140e96f88ccc393a9a71","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:273","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','273','53ad01b53c0dc3c60374b7428597d1052362338be653140e96f88ccc393a9a71','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:274','mayalex_normativos','03_FAMILIA','El protutor intervendrá en las funciones de la tutela, para asegurar su recto ejercicio.

La designación del protutor se hará en la misma forma que la del tutor. Puede recaer en parientes del pupilo o en otras personas, siempre que reúnan las condiciones de notoria honradez y arraigo.','274','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":314,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"aecf68302959888328e4e7cd8e068b09b9a7e99b444fdaa34783ba0e8b714077","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:274","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','274','aecf68302959888328e4e7cd8e068b09b9a7e99b444fdaa34783ba0e8b714077','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:275','mayalex_normativos','03_FAMILIA','El protutor está obligado:

1) A intervenir en el inventario y avalúo de los bienes del menor y en la calificación y otorgamiento de la garantía que debe prestar el tutor;

2) A defender los derechos del menor en juicio y fuera de él, siempre que estén en oposición con los intereses del tutor;

3) A promover el nombramiento de tutor cuando proceda la remoción del que estuviere ejerciéndola, o cuando la tutela quede vacante o abandonada;

4) A intervenir en la rendición de cuentas del tutor; y,
5) A ejercer las demás atribuciones que le señale la Ley.','275','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":315,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"fdbac4ded86e5ec96a863f3c5b419164edc7f7f912f0e1913fecf30c30afda9a","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:275","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','275','fdbac4ded86e5ec96a863f3c5b419164edc7f7f912f0e1913fecf30c30afda9a','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:276','mayalex_normativos','03_FAMILIA','Cuando hubiere conflicto de intereses entre varios pupilos sujetos a una misma tutela, el Juez les nombrará tutores específicos.','276','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":316,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"e595e7cad4370639d0ff6d752cdbfb43e65657f36dad28ac9c8cac9ed2148999","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:276","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','276','e595e7cad4370639d0ff6d752cdbfb43e65657f36dad28ac9c8cac9ed2148999','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:277','mayalex_normativos','03_FAMILIA','Mientras no se nombre tutor y protutor y no se disciernan los cargos, el Juez de oficio, o a solicitud del Ministerio Público, deberá dictar las providencias necesarias para el cuidado de la persona del menor o incapacitado y la seguridad de sus bienes.','277','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":317,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"48eda3b24157de60d1e2f581e15d262a28393ddcab1ec54242c93d36d3216b78","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:277","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','277','48eda3b24157de60d1e2f581e15d262a28393ddcab1ec54242c93d36d3216b78','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:278','mayalex_normativos','03_FAMILIA','Los directores o superiores de los establecimientos de asistencia social, que acojan menores o incapacitados, son tutores y representantes legales de los mismos, desde el momento de su ingreso, y su cargo no necesita discernimiento.','278','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":318,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"b5ea19f6c10dd3e6b2ec0aad983d578073b608640dd4c53073db18684eff3663","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:278","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','278','b5ea19f6c10dd3e6b2ec0aad983d578073b608640dd4c53073db18684eff3663','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:279','mayalex_normativos','03_FAMILIA','Los Institutos de asistencia pública pueden confiar al menor internado, que carezca de padres, ascendientes y hermanos, a personas de notoria moralidad, que dispongan de medios económicos para proporcionarle, alimentos, instrucción y educación. La dirección del establecimiento debe estar frecuentemente informada de las condiciones en que desarrolla la vida del menor y, en caso de abandono, o cambio de circunstancias, recogerle e internarlo de nuevo.','279','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":319,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"814e0da8265abc3022cb698a5a6302a1481a5b54a202c428fe855e7237a0e177","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:279","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','279','814e0da8265abc3022cb698a5a6302a1481a5b54a202c428fe855e7237a0e177','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:280','mayalex_normativos','03_FAMILIA','Las facultades de los tutores, respecto de los bienes que el menor o incapacitado tuviere fuera de la República, se ejercitarán conforme a la ley del país en que dichos bienes se hayan situados.','280','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":320,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"81daffcafb8e9fb565f0873ef5bed1fe48b3452a158819ab4a209e77188debb1","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:280","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','280','81daffcafb8e9fb565f0873ef5bed1fe48b3452a158819ab4a209e77188debb1','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:281','mayalex_normativos','03_FAMILIA','Las disposiciones relativas a los tutores, regirán para las personas que administran bienes de menores o incapaces, en casos determinados.','281','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":321,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"fff659d45cd6da35ed989d4f657aa548a54ac2d0a74de79d900bf4aa9a937bdc","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:281","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','281','fff659d45cd6da35ed989d4f657aa548a54ac2d0a74de79d900bf4aa9a937bdc','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:282','mayalex_normativos','03_FAMILIA','No puede ser tutor(a) ni protutor(a):

1) El(la) menor de edad ni el incapacitado(a);
2) Quien hubiere sido condenado(a) por robo, hurto, estafa, falsedad, delitos contra la libertad e integridad física, psicológica y sexual de las personas, violencia doméstica, violencia intrafamiliar, maltrato por transgresión, explotación económica, explotación sexual comercial, adopción ilegal u otros delitos de orden común que merezcan pena mayor de dos (2) años;
3) Quien hubiere sido removido(a) de otra tutela, o no hubiere rendido cuentas de su administración, o si habiéndolas rendido, no estuviesen aprobadas;
4) El(la) ebrio(a) consuetudinario(a), quien habitualmente consuma drogas, sustancias psicotrópicas o estupefacientes; sea adicto a los juegos prohibidos, el(la) vago(a) y el(la) de notoria mala conducta;
5) El(la) fallido(a) o concursado(a), mientras no haya obtenido su rehabilitación;
6) Quien tenga pendiente litigio propio o como representante legal de tercera persona o de sus ascendientes, descendientes o cónyuge, con el(la) niño(a) o incapacitado(a);
7) Quien haya perdido el ejercicio de la Patria Potestad o la administración de los bienes de sus hijos(as);
8) El(la) acreedor(a) o el deudor(a) del (la) niño(a) por cantidad apreciable en relación con los bienes del (la) niño(a), a juicio del(la) Juez(a), a menos que con conocimiento de causa, haya sido nombrado por testamento;
9) Quien no tenga domicilio en la República;
10) El(la)ciego(a);
11) El que padezca de enfermedad incurable o contagiosa;
12) El padrastro o madrastra de su hijastro(a); y,
13) Quienes no sepan leer ni escribir.','282','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":322,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"GACETA_33222_D35_2013","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"0285785d2856b060bc8fb006267f2a7b876e3a695afbb04a5bcbe6a03a60a0a2","ubicacion":["CAPÍTULO II","DE LA INHABILIDAD Y EXCUSAS PARA LA TUTELA"],"constancias":[{"nota":134,"tipo":"REFORMA","texto":"Artículo 282. Reformado mediante Decreto 35-2013, del 27 de febrero de 2013. Publicado en el Diario Oficial La Gaceta No. 33,222 de fecha 6 de septiembre de 2013.","decretos":["35-2013"]},{"nota":null,"tipo":"TEXTO_OFICIAL_GACETA","decretos":["35-2013"],"texto":"Texto tomado del D.35-2013 (La Gaceta No. 33,222), que coincide en sustancia con la edición CEDIJ (similitud 0.966); sha256 del texto de la edición: 95ffc7af4e1cfe4fbdb2c375d340b057e03a9729d7c058a316594b13fd3722f3."}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS","TEXTO_OFICIAL_GACETA"],"sustituye_id_legacy":"v2familia:mayalex_normativos:282","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY: texto oficial del D.35-2013 (Gaceta 33,222)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','282','0285785d2856b060bc8fb006267f2a7b876e3a695afbb04a5bcbe6a03a60a0a2','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:283','mayalex_normativos','03_FAMILIA','Los tutores o protutores a quienes sobrevenga alguna de las incapacidades que se mencionan en el Artículo anterior, serán separados de su cargo por resolución judicial, previa denuncia hecha por el MinisterioPúblico o algún pariente del pupilo y comprobación de los hechos.','283','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":323,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"674cc4b24ddbc8fcde30ef7b8a821473f733e5e3cbcdf07a17781176a57b9320","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:283","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','283','674cc4b24ddbc8fcde30ef7b8a821473f733e5e3cbcdf07a17781176a57b9320','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:284','mayalex_normativos','03_FAMILIA','Serán también removidos de tutela y pro tutela:

1) Quienes demuestren negligencia, ineptitud o infidelidad en el desempeño del cargo;

2) Quienes incitaren al pupilo a la corrupción o al delito;
3) Quienes emplearen maltrato con el menor;
4) Quienes a sabiendas hayan cometido inexactitud en el inventario, omitiendo bienes o créditos activos o pasivos; y,
5) Quienes se ausentaren por más de seis (6) meses del lugar en que desempeñen la tutela y protutela.','284','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":324,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"c4abff2ed05e9fabe621f6614189e2911ae76883c8d7890d296da7ef5f723670","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:284","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','284','c4abff2ed05e9fabe621f6614189e2911ae76883c8d7890d296da7ef5f723670','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:285','mayalex_normativos','03_FAMILIA','Pueden excusarse de la tutela y pro tutela:

1) Quienes tengan a su cargo otra tutela o protutela;
2) Los mayores de sesenta (60) años;
3) Quienes tengan bajo su patria potestad tres (3) o más hijos;
4) Quienes por sus limitados recursos no puedan atender el cargo sin menoscabo de su subsistencia;
5) Quienes padezcan enfermedad que les impida cumplir los deberes de su cargo; y,
6) Quienes tengan que ausentarse de la República por más de un (1) año.','285','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":325,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"0115fbaa1d7d594459e31c14b75a4b7f3d5b0672db720b0a2e0c5a1dd9b095ae","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:285","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','285','0115fbaa1d7d594459e31c14b75a4b7f3d5b0672db720b0a2e0c5a1dd9b095ae','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:286','mayalex_normativos','03_FAMILIA','Quienes no fueren parientes del menor o incapacitado, no estarán obligados a aceptar la tutela o pro tutela si hubiere personas llamadas por la Ley, que no tengan excusas o impedimentos para ejercer aquellos cargos.','286','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":326,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"158b78571c00994f20a8147944c789a7e366b3782bba80940b4a058e919ba2a6","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:286","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','286','158b78571c00994f20a8147944c789a7e366b3782bba80940b4a058e919ba2a6','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:287','mayalex_normativos','03_FAMILIA','El tutor y el protutor no entrarán a ejercer sus cargos, sino después de discernidos por el Juez. Ninguna tutela puede ser discernida sin haberse cumplido todos los requisitos que para su ejercicio exige la Ley; salvo el caso del artículo 278 de este Código.','287','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":327,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"821023bf7cb3c540071758e4ca36ff40ec3c9dc4e93ebfd4ef2a5f3e046b61c8","ubicacion":["CAPÍTULO III","DEL EJERCICIO DE LA TUTELA"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:287","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','287','821023bf7cb3c540071758e4ca36ff40ec3c9dc4e93ebfd4ef2a5f3e046b61c8','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:288','mayalex_normativos','03_FAMILIA','El tutor procederá al inventario y avalúo de los bienes del menor o incapacitado, dentro de los treinta (30) días siguientes a la aceptación del cargo, plazo que podrá ser restringido o ampliado prudencialmente por el Juez, según las circunstancias.

En ningún caso, ni aún por disposición del testador, quedará el tutor eximido de esta obligación.','288','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":328,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"6b87bd90de32a52684bd490168d8d047f1a66792a204b038f5c65fcbd95abbbb","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:288","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','288','6b87bd90de32a52684bd490168d8d047f1a66792a204b038f5c65fcbd95abbbb','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:289','mayalex_normativos','03_FAMILIA','Practicado el inventario, el tutor y el protutor quedan solidariamente obligados a promover la constitución de la garantía, salvo que no haya bienes, o que tratándose de tutor testamentario hubiere sido relevado de esta obligación por el testador, en cuanto a los bienes objeto de la herencia, donación o legado.','289','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":329,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"25adbb6586d377e305a021ec13279e70b023a0f9fcacf03e8e07e328685df099","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:289","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','289','25adbb6586d377e305a021ec13279e70b023a0f9fcacf03e8e07e328685df099','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:290','mayalex_normativos','03_FAMILIA','Cuando con posterioridad al discernimiento de la tutela, sobrevenga o se descubra causa que haga obligatoria la caución, lo hará saber al Juez, el propio tutor o el protutor o el Ministerio Público, para el efecto de la constitución de la garantía.','290','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":330,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"2aeb0563e4c70e148fb5f068472ec7a567c6c8932aeb92f5ae999843317bc3da","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:290","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','290','2aeb0563e4c70e148fb5f068472ec7a567c6c8932aeb92f5ae999843317bc3da','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:291','mayalex_normativos','03_FAMILIA','La garantía deberá asegurarse:

1) El importe de los bienes muebles que reciba el tutor;
2) El promedio de la renta de los bienes, en los últimos tres (3) años anteriores a la tutela; y,
3) Las utilidades que durante un (1) año pueda percibir el pupilo de cualquier empresa.','291','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":331,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"8fda9249477e0d3673fa00548f36eff485562e961272d106b5ffd9de2a88af88","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:291","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','291','8fda9249477e0d3673fa00548f36eff485562e961272d106b5ffd9de2a88af88','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:292','mayalex_normativos','03_FAMILIA','La garantía deberá aumentarse o disminuirse, según aumente o disminuya el valor de los bienes expresados o el de las cosas en que aquélla esté constituida.','292','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":332,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"898f4e20f6a7725352786a423ecba1a3c874298d4cde507feca77a8533fc356d","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:292","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','292','898f4e20f6a7725352786a423ecba1a3c874298d4cde507feca77a8533fc356d','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:293','mayalex_normativos','03_FAMILIA','La garantía deberá consistir en hipoteca, prenda o fianza otorgada por alguna institución bancaria o legalmente autorizada para el efecto. La garantía personal y aún la caución juratoria, pueden admitirse por el Juez cuando, a su juicio, fueren suficientes tomando en cuenta el valor de los bienes que vaya a administrar el tutor y la solvencia y buena reputaciónde éste.','293','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":333,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"88974850c8774606e1e30f558a8f498519d6cf05322e48eda5ba777ea179c932","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:293","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','293','88974850c8774606e1e30f558a8f498519d6cf05322e48eda5ba777ea179c932','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:294','mayalex_normativos','03_FAMILIA','La garantía prendaría que preste el tutor, se constituirá depositado los efectos o valores en una institución de crédito autorizada para recibir depósitos y, a falta de ella, en una persona de notorio arraigo.','294','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":334,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"a9a18deb6065cb1c94040fb8c3680898545530b0445f943e3464e312bc1efcba","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:294","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','294','a9a18deb6065cb1c94040fb8c3680898545530b0445f943e3464e312bc1efcba','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:295','mayalex_normativos','03_FAMILIA','El Juez fijará, a solicitud y propuesta del tutor, la pensión alimenticia, de acuerdo con el inventario y las circunstancias del pupilo, sin perjuicio de alterarla, según el aumento o disminución del patrimonio y otros motivos que apreciará el tribunal.','295','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":335,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"262e4b721546f07ef203738728f846e1c96a6adc52c7d96aa42ba1e2867d9f77","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:295","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','295','262e4b721546f07ef203738728f846e1c96a6adc52c7d96aa42ba1e2867d9f77','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:296','mayalex_normativos','03_FAMILIA','El tutor, dentro del primer mes de ejercer su cargo, someterá a la aprobación del Juez, el presupuesto de gastos de administración para el año.

Para los gastos extraordinarios fuera de presupuesto que pasen de Quinientos Lempiras (L.500.00), necesitará el tutor autorización judicial.','296','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":336,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"114fd4d446a201a954880ffd84e63a28a3212b699a9ad5886e5b57b64d279cb4","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:296","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','296','114fd4d446a201a954880ffd84e63a28a3212b699a9ad5886e5b57b64d279cb4','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:297','mayalex_normativos','03_FAMILIA','Las alhajas, muebles preciosos, efectos públicos, bonos, acciones y valores, que a juicio del Juez no hayan de estar en poder del tutor, serán depositados en un establecimiento autorizado por la Ley para recibir depósitos.','297','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":337,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"a3d4f2658989d5358e4b73d7ccc2cf0348fe08e2ed9954e6f3ccc74917890765","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:297","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','297','a3d4f2658989d5358e4b73d7ccc2cf0348fe08e2ed9954e6f3ccc74917890765','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:298','mayalex_normativos','03_FAMILIA','El tutor destinará al menor a la carrera, oficio o profesión que éste elija, según sus circunstancias. Si ya había iniciado alguna de estas actividades durante la patria potestad, el tutor no puede variarla sin autorización del Juez, para lo cual deberán tomarse en cuenta las aptitudes y circunstancias del menor.','298','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":338,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"426f4be8dd6fc7d3b3a31035c4a60b6921b7dd7555918ccec2e92cec964cb45c","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:298","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','298','426f4be8dd6fc7d3b3a31035c4a60b6921b7dd7555918ccec2e92cec964cb45c','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:299','mayalex_normativos','03_FAMILIA','El pupilo debe respeto y obediencia al tutor. Este tiene respecto de aquél, las facultades de los padres, con las limitaciones que la Ley establece.','299','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":339,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"ae2bcbf04acbb31d8970b141cc538aa453194687a865a5f6583d3ee2aec39e10","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:299","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','299','ae2bcbf04acbb31d8970b141cc538aa453194687a865a5f6583d3ee2aec39e10','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:300','mayalex_normativos','03_FAMILIA','El tutor necesita autorización judicial para:

1) Enajenar o gravar bienes inmuebles o derechos reales del menor o incapacitado; para dar los primeros en arrendamiento por más de tres (3) años, o con anticipo de renta por más de un (1) año; para hacer oreconocer mejoras que no sean necesarias para constituir servidumbres pasivas, y en general, para celebrar otra clase de contratos que afecten elpatrimonio del pupilo, siempre que pasen de Quinientos Lempiras (L.500.00).

Los contratos a que se refiere este inciso no pueden ser prorrogados;

2) Tomar dinero a mutuo, debiendo sujetarse a las condiciones y garantías que acuerde el Juez;

3) Repudiar herencias, legados y donaciones;
4) Transigir o comprometer en árbitros, las cuestiones en que el pupilo tuviere interés;
5) Hacerse pago de los créditos que tenga contra el menor o incapacitado; y,
6) Resolver la forma, condiciones y garantías en que debe colocar el dinero del pupilo.','300','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":340,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"508ad7fbc0b4651b47cae747461a00d26cd50c91a426bfd405fd7a0dc0e68f12","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:300","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','300','508ad7fbc0b4651b47cae747461a00d26cd50c91a426bfd405fd7a0dc0e68f12','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:301','mayalex_normativos','03_FAMILIA','La venta de valores comerciales o industriales, títulos de renta, acciones, bonos, frutos y ganado, podrá hacerse extrajudicialmente, pero nunca por menor valor del que se cotice en la plaza el día de la venta, lo cual deberá comprobar el tutor al rendir sus cuentas.','301','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":341,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"f2dfad58d4897cf7e79651ad2bd1ebc87f3392345cd26405f1d3bd5730fd79b0","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:301","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','301','f2dfad58d4897cf7e79651ad2bd1ebc87f3392345cd26405f1d3bd5730fd79b0','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:302','mayalex_normativos','03_FAMILIA','El tutor responde de los intereses legales del capital del pupilo, cuando por su omisión o negligencia, quedare improductivo o sin empleo.','302','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":342,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"35cedea1e8d20bf0382fde4816ddad647db5ef0a85300923a928d7c784dde8b3","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:302","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','302','35cedea1e8d20bf0382fde4816ddad647db5ef0a85300923a928d7c784dde8b3','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:303','mayalex_normativos','03_FAMILIA','El tutor no puede, sin autorización judicial, liquidar la empresa que forma parte del patrimonio del menor o variar el comercio o industria a que éste o sus causantes hubieren estado dedicados.','303','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":343,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"e37fd672278887387d1c9fb4babdac18729d7ec04950f20cf4d2c5ba0fb51b91","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:303","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','303','e37fd672278887387d1c9fb4babdac18729d7ec04950f20cf4d2c5ba0fb51b91','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:304','mayalex_normativos','03_FAMILIA','Quedan prohibidos al tutor los actos siguientes:

1) Contratar por sí o por interpósita persona, con el menor o incapacitado, o aceptar contra él créditos, derechos o acciones, a no ser que resulten de subrogación legal;

2) Disponer a título gratuito de los bienes del menor o incapacitado;
3) Aceptar donaciones del ex pupilo, sin estar aprobadas y canceladas las cuentas de su administración salvo cuando el tutor fuere ascendiente, cónyuge o hermano donante;
4) Hacer remisión voluntaria de derechos del menor o incapacitado; y,
5) Aceptar la institución de beneficiario en seguros a su favor, provenientes de su pupilo.','304','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":344,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"1728198a8a485b5cb4b1159a6db05d561f4cec93e81ecad0968e5d92b6f8396c","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:304","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','304','1728198a8a485b5cb4b1159a6db05d561f4cec93e81ecad0968e5d92b6f8396c','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:305','mayalex_normativos','03_FAMILIA','Tampoco podrán contratar acerca de bienes del menor o incapacitado, por sí o por interpósita persona, los parientes del tutor, salvo que éstos sean coherederos o copartícipes del pupilo.','305','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":345,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"a1f591d0981469d2f0d9fda1bc21ad3cc540cc5a4b2b9d0aea04581d6e4b7e5c","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:305","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','305','a1f591d0981469d2f0d9fda1bc21ad3cc540cc5a4b2b9d0aea04581d6e4b7e5c','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:306','mayalex_normativos','03_FAMILIA','El tutor no puede reconocer hijos del pupilo, sino con el consentimiento expreso de éste, y en ningún caso los del incapaz, ni consentir expresa o tácitamente las resoluciones desfavorables al pupilo.','306','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":346,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"7269d6b5d87378771941b4120a9c6f8ed7aa013ff00410d8c1398d0299fd5fb1","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:306","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','306','7269d6b5d87378771941b4120a9c6f8ed7aa013ff00410d8c1398d0299fd5fb1','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:307','mayalex_normativos','03_FAMILIA','Durante el ejercicio de la tutela, el protutor está obligado a defender los derechos del menor en juicio y fuera de él, cuando estén en oposición con los intereses del tutor, y a promover el nombramiento, cuando proceda la remoción del que la tuviera en ejercicio, o cuando la tutela quede vacante o abandonada.','307','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":347,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"4a26ae6900f094cbaa9c9b05aabe2fd0fdae10f1723277ee6b1c89b92d0817a5","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:307","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','307','4a26ae6900f094cbaa9c9b05aabe2fd0fdae10f1723277ee6b1c89b92d0817a5','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:308','mayalex_normativos','03_FAMILIA','La tutela y pro tutela dan derecho a una retribución que se pagará anualmente y que no bajará del cinco (5%) por ciento ni excederá del quince (15%) por ciento anual de las rentas y productos líquidos de los bienes del pupilo.

Cuando la retribución no hubiere sido fijada en el testamento o cuando sin mediar negligencia del tutor no hubiere rentas o productos líquidos, la fijará el Juez teniendo en cuenta la importancia del caudal del pupilo y el trabajo que ocasione el ejercicio de la tutela. La retribución se distribuirá entre el tutor y el protutor, correspondiendo al primero el (75%) setenta y cinco por ciento y al segundo el veinticinco (25%) por ciento restante.','308','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":348,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"1d9744bc740a47c417c7c21869a65b682478d96b02eb41ebe659c8c023442021","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:308","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','308','1d9744bc740a47c417c7c21869a65b682478d96b02eb41ebe659c8c023442021','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:309','mayalex_normativos','03_FAMILIA','Cuando el tutor y el protutor hubieren sido removidos por su culpa no tendrán derecho a recibir retribución alguna.','309','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":349,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"ecf29e0df19ca866fcca00cce8e9abd777b26262aafc35e40ca9a8b8b12e9d2c","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:309","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','309','ecf29e0df19ca866fcca00cce8e9abd777b26262aafc35e40ca9a8b8b12e9d2c','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:310','mayalex_normativos','03_FAMILIA','El tutor está obligado a llevar cuenta exacta y documentada de todas las operaciones de su administración. Al final de su cargo, presentará una memoria que resuma los actos llevados a cabo.','310','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":350,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"2c66ca398301226db03dcf97f0dcc2cb4f1520a63a517d7a36094b1395a74fc4","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:310","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','310','2c66ca398301226db03dcf97f0dcc2cb4f1520a63a517d7a36094b1395a74fc4','OLA5_CF_2023_01',now())
