('OLA5_CF_2023_01:CODIGO_FAMILIA:311','mayalex_normativos','03_FAMILIA','El tutor deberá rendir cuentas anualmente y al concluirse la tutela o cesar en su cargo.','311','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":351,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"de2dd0d6c1dbdfc1e129a53cd59cf7bb23cb0288fd2f9e3da01ff6335dafe16d","ubicacion":["CAPÍTULO IV","DE LA RENDICIÓN DE CUENTAS DE LA TUTELA"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:311","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','311','de2dd0d6c1dbdfc1e129a53cd59cf7bb23cb0288fd2f9e3da01ff6335dafe16d','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:312','mayalex_normativos','03_FAMILIA','La rendición anual de cuentas se hará ante el Juez con intervención del protutor y del Ministerio Público.','312','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":352,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"70dbaeb39b41ea653f6a4046477618c37a65eaa3e99f3211d187b963eb1f078d","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:312","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','312','70dbaeb39b41ea653f6a4046477618c37a65eaa3e99f3211d187b963eb1f078d','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:313','mayalex_normativos','03_FAMILIA','La rendición final de cuentas se hará por el tutor o sus herederos, al ex pupilo o a quién lo represente, dentro de (60) sesenta días contados desde que terminó el ejercicio de la tutela.','313','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":353,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"74cbf63deb0638012a80b6cb24a0359f8b32acfbca8ac3a182ebaa92aa5a72d8","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:313","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','313','74cbf63deb0638012a80b6cb24a0359f8b32acfbca8ac3a182ebaa92aa5a72d8','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:314','mayalex_normativos','03_FAMILIA','El tutor que sustituya a otro está obligado a exigir la entrega de bienes y la rendición de cuentas al que lo ha precedido. Si no lo hiciere, es responsable de los daños y perjuicios que por su omisión se siguieren al pupilo.','314','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":354,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"6e1b382a6d585caddbd0783b579ef3650253143df3a105448cfa31a31d2e10cd","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:314","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','314','6e1b382a6d585caddbd0783b579ef3650253143df3a105448cfa31a31d2e10cd','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:315','mayalex_normativos','03_FAMILIA','Las cuentas deben ir acompañadas de sus documentos justificativos.

Sólo podrán excusarse la comprobación de los gastos en que no se acostumbre recoger recibo.','315','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":355,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"e606ecbb7a31879ccb68f5d21b8a13e427be05f03582d733cbd0e014670feab1","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:315","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','315','e606ecbb7a31879ccb68f5d21b8a13e427be05f03582d733cbd0e014670feab1','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:316','mayalex_normativos','03_FAMILIA','Los gastos de la rendición de cuentas, correrán a cargo del menor o incapacitado.','316','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":356,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"ad9140a66c954f71aa8a654baa371f2f4597cf43e92c4ceaa2d59b7072823ce2","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:316","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','316','ad9140a66c954f71aa8a654baa371f2f4597cf43e92c4ceaa2d59b7072823ce2','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:317','mayalex_normativos','03_FAMILIA','El tutor, concluida la tutela, está obligado a entregar bajo inventario a quien fue su pupilo, todos los bienes y documentos que le pertenezcan.

Esta obligación no se suspende por estar pendiente la rendición de cuentas.','317','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":357,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"2b37d2de827f000bf8ba402b766ea35e1f2718e92db8be02725009276e7adc0d","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:317","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','317','2b37d2de827f000bf8ba402b766ea35e1f2718e92db8be02725009276e7adc0d','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:318','mayalex_normativos','03_FAMILIA','El saldo de las cuentas que resultare a favor o en contra del tutor, producirá interés legal.

En el primer caso, desde que el pupilo sea requerido para el pago, previa entrega de los bienes; en el segundo, desde la rendición de cuentas, si hubieran sido rendidas dentro del término legal, y en caso contrario, desde que ésta expire.','318','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":358,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"4c0114cc7e512254ea4500b2cb32096e3c4f182cf7b8911ce493007b8fe2e6b1","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:318","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','318','4c0114cc7e512254ea4500b2cb32096e3c4f182cf7b8911ce493007b8fe2e6b1','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:319','mayalex_normativos','03_FAMILIA','Las acciones u obligaciones que recíprocamente corresponden al tutor y al ex pupilo, por razón del ejercicio de la tutela, se extinguen a los cinco (5) años de concluida ésta.','319','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":359,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"d4dc950705e942978784f64fbb6774b87c00cc9d153dda94fdb377ba4e3035e1","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:319","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','319','d4dc950705e942978784f64fbb6774b87c00cc9d153dda94fdb377ba4e3035e1','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:320','mayalex_normativos','03_FAMILIA','La tutela termina:

1) Por llegar el(la) pupilo(a) a su mayoría de edad;
2) Por el matrimonio del(la) pupilo(a) que hubiere cumplido dieciocho (18) años; y,
3) Por la muerte del(la) pupilo(a).','320','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":360,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"GACETA_33222_D35_2013","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"214dc18ddad0fd862e60a7f6f472cf9ec3254ac404c122b01930d2d2c250064e","ubicacion":[],"constancias":[{"nota":135,"tipo":"REFORMA","texto":"Artículo 320. Reformado mediante Decreto 35-2013, del 27 de febrero de 2013. Publicado en elDiario Oficial La Gaceta No. 33,222 de fecha 6 de septiembre de 2013.","decretos":["35-2013"]},{"nota":null,"tipo":"TEXTO_OFICIAL_GACETA","decretos":["35-2013"],"texto":"Texto tomado del D.35-2013 (La Gaceta No. 33,222), que coincide en sustancia con la edición CEDIJ (similitud 1.000); sha256 del texto de la edición: d19bf9fe44372c68da39bfa5cad0509b920cc2f574760ee167549d0e429734d6."}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS","TEXTO_OFICIAL_GACETA"],"sustituye_id_legacy":"v2familia:mayalex_normativos:320","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY: texto oficial del D.35-2013 (Gaceta 33,222)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','320','214dc18ddad0fd862e60a7f6f472cf9ec3254ac404c122b01930d2d2c250064e','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:321','mayalex_normativos','03_FAMILIA','Al incapacitado de los derechos civiles en virtud de sentencia pronunciada en causa criminal, se le nombrará un curador.

Esta cúratela durará lo que dure la interdicción y se limitará a la administración de los bienes y a la representación en juicio del penado.','321','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":361,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"940fce0fbb77b342f5472103ac861895e2f67ab160c7ccf9c161bdca5a2e497e","ubicacion":["CAPÍTULO V","DE LA CURATELA"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:321","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','321','940fce0fbb77b342f5472103ac861895e2f67ab160c7ccf9c161bdca5a2e497e','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:322','mayalex_normativos','03_FAMILIA','Habrá lugar al nombramiento de curador para la administración de los bienes y negocios de una persona, cuando por ausencia se halle imposibilitado de hacer valer sus derechos por sí o por medio de representante legalmente constituido y se desconozca su paradero.','322','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":362,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"1fc3c8154f57a42bc12f2e9aae6575171aaf777338ce39d2af77ebbbe0564d9e","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:322","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','322','1fc3c8154f57a42bc12f2e9aae6575171aaf777338ce39d2af77ebbbe0564d9e','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:323','mayalex_normativos','03_FAMILIA','Podrán provocar el nombramiento en los casos a que se refiere este Capítulo, las personas designadas en el Artículo 270, el representante del Ministerio Público y los acreedores del ausente, para responder a sus demandas.','323','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":363,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"4751f82558aa4e82aa59286950044b2d276e720a48dd4355bfbcbf4645b5edc5","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:323","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','323','4751f82558aa4e82aa59286950044b2d276e720a48dd4355bfbcbf4645b5edc5','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:324','mayalex_normativos','03_FAMILIA','Lo dispuesto para la tutela se observará también respecto a la cúratela en cuanto fuere aplicable y no sea contrario a lo determinado en este Capítulo.','324','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":364,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"2987035d2f8131e075e38d947617840bc83ff75ca8f1e1c2ee7cccbcd2ac8aa4","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:324","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','324','2987035d2f8131e075e38d947617840bc83ff75ca8f1e1c2ee7cccbcd2ac8aa4','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:325','mayalex_normativos','03_FAMILIA','La Ley reconoce el parentesco de consanguinidad dentro del cuarto grado, el de afinidad dentro del segundo grado, y el civil, que nace de la adopción, y sólo existe entre el adoptante y el adoptado.','325','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":365,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"51c264e0d6d9da9c1f726aef7ffe1faf255d13cb8777befe0d3b4dd8438c5c78","ubicacion":["TÍTULO IX","DEL PARENTESCO CAPÍTULOÚNICO"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:325","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','325','51c264e0d6d9da9c1f726aef7ffe1faf255d13cb8777befe0d3b4dd8438c5c78','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:326','mayalex_normativos','03_FAMILIA','Parentesco de consanguinidad es la relación o conexión que existe entre las personas que descienden de un mismo tronco o raíz, o que están unidos por los vínculos de sangre.','326','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":366,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"513189be32db71c6c2564db537b69095d3ba59c29c962e08a255c70605b4461a","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:326","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','326','513189be32db71c6c2564db537b69095d3ba59c29c962e08a255c70605b4461a','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:327','mayalex_normativos','03_FAMILIA','Parentesco de afinidad es el vínculo que une a los cónyuges con sus respectivos parientes consanguíneos. En la línea y en el grado en que una persona es pariente por consanguinidad con uno de los cónyuges,en la misma línea y en el mismo grado es pariente por afinidad con el otro cónyuge.','327','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":367,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"608e2fea14181c87c06d8d48020ff556f39d169cc4cc14e80470d3c62e313351","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:327","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','327','608e2fea14181c87c06d8d48020ff556f39d169cc4cc14e80470d3c62e313351','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:328','mayalex_normativos','03_FAMILIA','El parentesco se gradúa por el número de generaciones; cada generación constituye un grado.','328','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":368,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"b76ea5480c6cdefec183f1eaa7378f2f47a255d6e4351fd08694dd66bd59f071","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:328","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','328','b76ea5480c6cdefec183f1eaa7378f2f47a255d6e4351fd08694dd66bd59f071','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:329','mayalex_normativos','03_FAMILIA','La serie de generaciones o grados procedentes de un ascendiente común forma línea.','329','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":369,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"677938eab019e02fb8e78fbf1e1dcd35ff32f97df0bb65504411e67d5f4a4037","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:329","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','329','677938eab019e02fb8e78fbf1e1dcd35ff32f97df0bb65504411e67d5f4a4037','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:330','mayalex_normativos','03_FAMILIA','La línea es recta, cuando las personas descienden unas de otras, y colateral o transversal, cuando las personas provienen de un ascendiente común, pero no descienden unas de otras.','330','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":370,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"369743049664a8fb80363f8ce1b72684d31bd3f939524d2b7ee6970cbc58d165","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:330","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','330','369743049664a8fb80363f8ce1b72684d31bd3f939524d2b7ee6970cbc58d165','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:331','mayalex_normativos','03_FAMILIA','Cuando en la línea recta se cuenta bajando del tronco a los(las) otros(as) parientes, se llama descendente; y cuando se cuenta subiendo de uno de los(las) parientes al tronco se llama ascendente.

En la línea recta, sea ascendente o descendente, hay tantos grados como generaciones, o sea tanto como personas, sin incluirse la del tronco común.','331','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":371,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"GACETA_33222_D35_2013","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"2afb5d40655651a790a9683f7b7fc92cc87ec0d1c2862707881650c58c876498","ubicacion":[],"constancias":[{"nota":136,"tipo":"REFORMA","texto":"Artículo 331. Reformado mediante Decreto 35-2013, del 27 de febrero de 2013. Publicado en el Diario Oficial La Gaceta No.33,222 de fecha 6 de septiembre de 2013.","decretos":["35-2013"]},{"nota":null,"tipo":"TEXTO_OFICIAL_GACETA","decretos":["35-2013"],"texto":"Texto tomado del D.35-2013 (La Gaceta No. 33,222), que coincide en sustancia con la edición CEDIJ (similitud 0.904); sha256 del texto de la edición: a11b503e6f43344e063a22e2d851e74e6fa22b5e792c656a486d4162f25b94ad."}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS","TEXTO_OFICIAL_GACETA"],"sustituye_id_legacy":"v2familia:mayalex_normativos:331","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY: texto oficial del D.35-2013 (Gaceta 33,222)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','331','2afb5d40655651a790a9683f7b7fc92cc87ec0d1c2862707881650c58c876498','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:332','mayalex_normativos','03_FAMILIA','En la línea colateral los grados se cuentan igualmente por generaciones, subiendo desde la persona cuyo parentesco se requiere comprobar, hasta el ascendiente común y bajando desde éste hasta el otro pariente.','332','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":372,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"23ebd3c43367d57aebc6cf6a374cd5356a4a2072c199763233de7ddf6f13d0b8","ubicacion":[],"constancias":[{"nota":137,"tipo":"REFORMA","texto":"Artículo 332. Reformado mediante Decreto 35-2013, del 27 de febrero de 2013. Publicado en el Diario Oficial La Gaceta No.33,222 de fecha 6 de septiembre de 2013.","decretos":["35-2013"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":"v2familia:mayalex_normativos:332","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (reforma integrada): edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','332','23ebd3c43367d57aebc6cf6a374cd5356a4a2072c199763233de7ddf6f13d0b8','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:332-A','mayalex_normativos','03_FAMILIA','En los casos en que la Ley dispone que se oiga a los(as) parientes de una persona, se entenderán comprendidos(as) en esa denominación su cónyuge o compañero(a) de hogar en una unión de hecho debidamente reconocida y sus consanguíneos de uno u otro sexo mayores de edad. A falta de consanguíneos en suficiente número, serán oídos sus parientes por afinidad.

Serán preferidos(as) los y las descendientes y ascendientes a los colaterales, y entre éstos, a los de más cercano parentesco.

Los parientes serán citados y comparecerán a ser oídos verbalmente, en la forma prescrita por el Código Procesal Civil.','332-A','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":373,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"GACETA_33222_D35_2013","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"2c4f5d5d8a774873fd4d041cf7cfbee5c76999dc2864646f42d4433835f50702","ubicacion":[],"constancias":[{"nota":138,"tipo":"ADICION","texto":"Artículo 332- A. Reformado por Adición mediante Decreto 35-2013, del 27 de febrero de 2013. Publicado en el Diario Oficial La Gaceta No.33,222 de fecha 6 de septiembre de 2013.","decretos":["35-2013"]},{"nota":null,"tipo":"TEXTO_OFICIAL_GACETA","decretos":["35-2013"],"texto":"Texto tomado del D.35-2013 (La Gaceta No. 33,222), que coincide en sustancia con la edición CEDIJ (similitud 1.000); sha256 del texto de la edición: aa80faff89c46605e4650a457856745e19649305b43f0d44b306984a01c79898."}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS","TEXTO_OFICIAL_GACETA"],"sustituye_id_legacy":"v2familia:mayalex_normativos:332-A","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY: texto oficial del D.35-2013 (Gaceta 33,222)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','332-A','2c4f5d5d8a774873fd4d041cf7cfbee5c76999dc2864646f42d4433835f50702','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:333','mayalex_normativos','03_FAMILIA','El presente Código se aplicará a los actos originados a partir de su vigencia, así como a los efectos futuros de los actos originados bajo el imperio de las leyes anteriores. El nacimiento de los actos jurídicos ocurridos durante la vigencia de las leyes anteriores, se regirán por dichas leyes.','333','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":374,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"d8e0b899ebbad76208946a91a9cd9bc9e36ffde621afaca5cf08db71639f871e","ubicacion":["TÍTULO X","CAPÍTULO","ÚNICO","DE LAS DISPOSICIONES FINALES Y TRANSITORIAS"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:333","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','333','d8e0b899ebbad76208946a91a9cd9bc9e36ffde621afaca5cf08db71639f871e','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:334','mayalex_normativos','03_FAMILIA','La unión de hecho que se formalice fundándose en la unión iniciada con anterioridad a la vigencia de este Código, surtirá sus efectos únicamente en relación con el estado civil de los convivientes y sus hijos.','334','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":375,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"7884eab876cea2a3a630f0c9aa070d102ac825d57a031edab0fc5203d1c64a0f","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:334","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','334','7884eab876cea2a3a630f0c9aa070d102ac825d57a031edab0fc5203d1c64a0f','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:335','mayalex_normativos','03_FAMILIA','En tanto se crean los tribunales de familia preceptuados en el

Artículo 5 de este Código, conocerán de los asuntos relativos al mismo, los Tribunales en materia civil.','335','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":376,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"24c33cd7cdeb0f0b8fb9046712631938de8d730232e3b1e5d8161e2b4bc5ca65","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:335","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','335','24c33cd7cdeb0f0b8fb9046712631938de8d730232e3b1e5d8161e2b4bc5ca65','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:336','mayalex_normativos','03_FAMILIA','En las reglas relativas a la sucesión intestada y a la distribución de la herencia a que se refieren los Capítulos I y II, Título II, LibroIII del Código Civil, quedan abolidas las distinciones entre hijos legítimos y naturales.','336','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":377,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"33abd86124fc9caa1dfff239b5b373ae49df3826d696659be1a9e389b5e6cc2b","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:336","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','336','33abd86124fc9caa1dfff239b5b373ae49df3826d696659be1a9e389b5e6cc2b','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:337','mayalex_normativos','03_FAMILIA','Quedan derogadas todas las disposiciones contenidas en las leyes, decretos-leyes y decretos que se opongan al presente Código.','337','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":378,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"197cd427dca315d4c0450ea44c37429b9a8a34f3a9e3afeb58c31725c50d199f","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:337","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','337','197cd427dca315d4c0450ea44c37429b9a8a34f3a9e3afeb58c31725c50d199f','OLA5_CF_2023_01',now()),
('OLA5_CF_2023_01:CODIGO_FAMILIA:338','mayalex_normativos','03_FAMILIA','El presente Código entrará en vigencia un año después de su publicación en el Diario Oficial "La Gaceta".','338','Código de Familia de Honduras (Decreto No. 76-84)','{"norm_id":"HN:CODIGO_FAMILIA","instrumento_id":"CODIGO_FAMILIA","ingest_batch":"OLA5_CF_2023_01","ola":"OLA5","ordinal":379,"decreto":"76-84","gaceta_original":"24,394","fecha_gaceta_original":"1984-08-16","texto_origen":"PDF_CONSOLIDADO_CEDIJ_2023_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo de Familia (Actualizado con Reformas Ley de Adopciones).pdf», Word 2019, 17-oct-2023; notas al pie secuenciales con la cita de cada decreto.","pdf_sha256":"c0bd8d618d2036a8f2adb2cc7f1ca4a02319db15986d8c1a2371f544a0d89023","article_sha256":"190615cab2ec36c436bc12b7cd970cbf98ad56edef840f50f3354eb5aeae47f8","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2familia:mayalex_normativos:338","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (2023) con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_FAMILIA','338','190615cab2ec36c436bc12b7cd970cbf98ad56edef840f50f3354eb5aeae47f8','OLA5_CF_2023_01',now())
ON CONFLICT (id) DO NOTHING;
DO $do$ DECLARE n int; BEGIN
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA5_CF_2023_01' AND metadata->>'norm_id' = 'HN:CODIGO_FAMILIA'
    AND instrumento_id = 'CODIGO_FAMILIA' AND jurisdiccion = 'HN' AND encode(sha256(convert_to(contenido, 'UTF8')), 'hex') = hash_contenido AND revision_pendiente = true AND es_norma_vigente IS NULL;
  IF n <> 379 THEN RAISE EXCEPTION 'post-insert prod (ocultas, hash correcto): % filas (esperadas 379)', n; END IF;
END $do$;
COMMIT;
